INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (1, 'en', 'Hence justice, right reason, and the recognition of man''s dignity cry out insistently for a cessation to the arms race. The stock-piles of armaments which have been built up in various countries must be reduced all round and simultaneously by the parties concerned. Nuclear weapons must be banned. A general agreement must be reached on a suitable disarmament program, with an effective system of mutual control. In the words of Pope Pius XII: "The calamity of a world war, with the economic and social ruin and the moral excesses and dissolution that accompany it, must not on any account be permitted to engulf the human race for a third time."', 'disarmament, arms race, nuclear weapons, mutual control, justice, peace', 'official_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, 'e43f6056bfe8871c');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (1, 'pl', 'Dlatego sprawiedliwość, prawy rozum i poczucie godności ludzkiej domagają się usilnie zaprzestania wyścigu zbrojeń; trzeba, aby zapasy broni, jakimi rozporządzają poszczególne państwa, zostały równocześnie i proporcjonalnie zmniejszone; aby broń jądrowa została zakazana, a wreszcie, by wszyscy doszli do porozumienia w sprawie odpowiedniego rozbrojenia pod skuteczną wzajemną kontrolą.', 'rozbrojenie, wyścig zbrojeń, broń jądrowa, wzajemna kontrola, sprawiedliwość, pokój', 'human_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, '5c3fbf3d3737110c');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (2, 'en', 'We acknowledge that this conviction owes its origin chiefly to the terrifying destructive force of modern weapons. It arises from fear of the ghastly and catastrophic consequences of their use. Thus, in this age which boasts of its atomic power, it no longer makes sense to maintain that war is a fit instrument with which to repair the violation of justice.', 'war, justice, atomic power, negotiation, deterrence, fear', 'official_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, '3ad449607c471762');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (2, 'pl', 'W naszej epoce, która szczyci się potęgą atomową, byłoby rzeczą obcą rozumowi uważać wojnę za odpowiedni środek do przywrócenia naruszonych praw.', 'wojna, sprawiedliwość, era atomowa, rokowania, odstraszanie', 'human_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, '322e363b8c8164bd');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (3, 'en', 'Peace is not merely the absence of war; nor can it be reduced solely to the maintenance of a balance of power between enemies; nor is it brought about by dictatorship. Instead, it is rightly and appropriately called an enterprise of justice. Peace results from that order structured into human society by its divine Founder, and actualized by men as they thirst after ever greater justice. The common good of humanity finds its ultimate meaning in the eternal law. But since the concrete demands of this common good are constantly changing as time goes on, peace is never attained once and for all, but must be built up ceaselessly. Moreover, since the human will is unsteady and wounded by sin, the achievement of peace requires a constant mastering of passions and the vigilance of lawful authority.', 'peace, justice, balance of power, common good, dictatorship', 'official_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, '2e9b744781da27bd');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (3, 'pl', 'Pokój nie jest jedynie brakiem wojny i nie daje się sprowadzić wyłącznie do zapewnienia równowagi sił przeciwstawnych, ani też nie rodzi się z despotycznego władztwa, lecz słusznie i właściwie zowie się dziełem sprawiedliwości.', 'pokój, sprawiedliwość, równowaga sił, dobro wspólne, dyktatura', 'human_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, '0a01dacd20181a71');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (4, 'en', 'Certainly, war has not been rooted out of human affairs. As long as the danger of war remains and there is no competent and sufficiently powerful authority at the international level, governments cannot be denied the right to legitimate defense once every means of peaceful settlement has been exhausted. State authorities and others who share public responsibility have the duty to conduct such grave matters soberly and to protect the welfare of the people entrusted to their care. But it is one thing to undertake military action for the just defense of the people, and something else again to seek the subjugation of other nations. Nor, by the same token, does the mere fact that war has unhappily begun mean that all is fair between the warring parties.', 'legitimate defense, just defense, war, subjugation, sovereignty', 'official_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, 'f17dff2a2b087cbb');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (4, 'pl', 'Dopóki istnieje niebezpieczeństwo wojny, a równocześnie brakuje międzynarodowej władzy posiadającej niezbędne kompetencje i wyposażonej w odpowiednią siłę, nie można odmawiać rządom prawa do koniecznej obrony, byle wyczerpały wpierw wszystkie środki pokojowych rokowań. Czym innym jest jednak prowadzić działania wojenne dla sprawiedliwej obrony narodów, a czym innym chcieć podporządkować sobie inne narody.', 'uprawniona obrona, sprawiedliwa obrona, wojna, podporządkowanie narodów', 'human_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, 'b2f0616580718933');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (5, 'en', 'The territory of neutral Powers is inviolable.', 'neutrality, neutral powers, inviolable territory, Hague', 'official_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, '126d1e6d85be7e99');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (5, 'pl', 'Terytorium mocarstw neutralnych jest nienaruszalne.', 'neutralność, mocarstwa neutralne, nienaruszalność terytorium, Konwencja Haska', 'human_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, 'b8f6f02214a28e0b');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (6, 'en', 'Belligerents are forbidden to move troops or convoys of either munitions of war or supplies across the territory of a neutral Power.', 'neutrality, belligerents, troops, convoys, transit', 'official_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, 'd1aa97d74aeaf4d8');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (6, 'pl', 'Stronom wojującym wzbronione jest przeprowadzanie przez terytorium mocarstwa neutralnego wojsk lub konwojów z amunicją bądź zaopatrzeniem wojennym.', 'neutralność, strony wojujące, wojska, konwoje, tranzyt', 'human_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, 'ba2d76fb36606a51');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (7, 'en', 'A neutral Power must not allow any of the acts referred to in Articles 2 to 4 to occur on its territory.', 'neutrality, duties of neutral powers, territory', 'official_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, 'cfe4a0c6c6c15d07');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (7, 'pl', 'Mocarstwo neutralne nie może dopuszczać na swoim terytorium do żadnego z czynów określonych w artykułach 2 do 4.', 'neutralność, obowiązki mocarstwa neutralnego, terytorium', 'human_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, '2ab24fe738015f62');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (8, 'pl', '[PLACEHOLDER — robocza treść AI, do zastąpienia tekstem ruchu] Bezpieczeństwo Rzeczypospolitej opiera się na dobrobycie obywateli, solidarności społecznej i odrzuceniu awanturnictwa geopolitycznego. Przekucie mieczy na lemiesze oznacza priorytet obrony terytorialnej i zdolności wytwórczych nad ekspedycyjnym uwikłaniem w cudze wojny.', 'lemiesz, suwerenność, pokój, obrona terytorialna', 'ai_drafted', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, 'f4c7fece1af0c0b5');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (9, 'pl', '[PLACEHOLDER — robocza treść AI, do zastąpienia tekstem ruchu] Strategia Podwójnego Dystansu zakłada równy, strategiczny dystans wobec rywalizujących bloków oraz zdolność do handlu i dyplomacji ze wszystkimi stronami przy zachowaniu nienaruszalności własnych granic.', 'podwójny dystans, neutralność czynna, bloki, niezależność', 'ai_drafted', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, 'cd886d5d9b8fa3fa');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (10, 'pl', '[PARAFRAZA ROBOCZA AI — do zastąpienia parafrazą autorstwa ruchu] Prawo jest zorganizowanym prawem jednostki do obrony; gdy staje się narzędziem legalnej grabieży, traci swój moralny autorytet.', 'bastiat, prawo, legalna grabież, własność, wolność', 'ai_drafted', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, 'f9756dc0c489c886');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (12, 'en', 'Or what king, as he goes to encounter another king in war, will not sit down first and consider whether he is able with ten thousand to meet him who comes against him with twenty thousand? Or else, while the other is yet a great way off, he sends an envoy and asks for conditions of peace.', 'royal reckoning, Luke 14, king, ten thousand, twenty thousand, delegation, terms of peace, prudence', 'official_translation', 'draft', 'World English Bible (WEB, public domain)', NULL, NULL, NULL, NULL, NULL, '9a3e68b20c3a67f3');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (12, 'pl', 'Albo który król jadąc na wojnę, potykać się z drugim królem, pierwej usiadłszy, nie radzi się, mógłliby się w dziesięć tysięcy spotkać z onym, który we dwadzieścia tysięcy jedzie przeciwko niemu? A jeźli nie, gdy on jeszcze jest daleko od niego, posły wyprawiwszy do niego, prosi o to, co należy do pokoju.', 'rachunek królewski, Łk 14, król, dziesięć tysięcy, dwadzieścia tysięcy, poselstwo, warunki pokoju, roztropność', 'official_translation', 'draft', 'Biblia Gdańska (wyd. 1881, domena publiczna)', NULL, NULL, NULL, NULL, NULL, 'ef9ef106a3505cc0');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (13, 'en', '“I am the good shepherd. The good shepherd lays down his life for the sheep. He who is a hired hand, and not a shepherd, who doesn’t own the sheep, sees the wolf coming, leaves the sheep, and flees. The wolf snatches the sheep and scatters them. The hired hand flees because he is a hired hand and doesn’t care for the sheep.', 'good shepherd, hireling, wolf, sheep, flight, Kuty bridge 1939, elite accountability, risk asymmetry', 'official_translation', 'draft', 'World English Bible (WEB, public domain)', NULL, NULL, NULL, NULL, NULL, 'ebe9f57ada632430');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (13, 'pl', 'Jam jest on dobry pasterz; dobry pasterz duszę swoję kładzie za owce. Lecz najemnik i ten, który nie jest pasterzem, którego nie są owce własne, widząc wilka przychodzącego, opuszcza owce i ucieka, a wilk porywa i rozprasza owce. A najemnik ucieka, iż jest najemnik i nie ma pieczy o owcach.', 'dobry pasterz, najemnik, wilk, owce, ucieczka, Kuty 1939, odpowiedzialność elit, asymetria ryzyka', 'official_translation', 'draft', 'Biblia Gdańska (wyd. 1881, domena publiczna)', NULL, NULL, NULL, NULL, NULL, '525c9793aeb0b655');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (14, 'en', 'He will judge between the nations, and will decide concerning many peoples. They shall beat their swords into plowshares, and their spears into pruning hooks. Nation shall not lift up sword against nation, neither shall they learn war any more. (Isaiah 2:4) Blessed are the peacemakers, for they shall be called children of God. (Matthew 5:9)', 'swords into plowshares, spears into pruning hooks, blessed are the peacemakers, sons of God, Isaiah, Matthew', 'official_translation', 'draft', 'World English Bible (WEB, public domain)', NULL, NULL, NULL, NULL, NULL, '1af1b401f551d6c8');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (14, 'pl', 'I będzie sądził między narodami, a będzie karał wiele ludzi. I przekują miecze swe na lemiesze, a włócznie swe na sierpy; nie podniesie naród przeciw narodowi miecza, ani się będą ćwiczyć do bitwy. (Iz 2, 4) Błogosławieni pokój czyniący; albowiem oni synami Bożymi nazwani będą. (Mt 5, 9)', 'miecze na lemiesze, włócznie na sierpy, błogosławieni pokój czyniący, synowie Boży, Izajasz, Mateusz', 'official_translation', 'draft', 'Biblia Gdańska (wyd. 1881, domena publiczna)', NULL, NULL, NULL, NULL, NULL, 'e43c79a1210b3d95');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (15, 'en', 'He said, “This will be the way of the king who shall reign over you: he will take your sons and appoint them as his servants, for his chariots and to be his horsemen; and they will run before his chariots. He will appoint them to him for captains of thousands and captains of fifties; and he will assign some to plow his ground and to reap his harvest; and to make his instruments of war and the instruments of his chariots. He will take your daughters to be perfumers, to be cooks, and to be bakers. He will take your fields, your vineyards, and your olive groves, even your best, and give them to his servants. He will take one tenth of your seed and of your vineyards, and give it to his officers and to his servants. He will take your male servants, your female servants, your best young men, and your donkeys, and assign them to his own work. He will take one tenth of your flocks; and you will be his servants.', 'Samuel, right of the king, chariots, conscription, tithe, militarism, tax servitude', 'official_translation', 'draft', 'World English Bible (WEB, public domain)', NULL, NULL, NULL, NULL, NULL, '75cc07955d8937b8');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (15, 'pl', 'I mówił: Toć będzie prawo króla, który królować ma nad wami: Syny wasze brać będzie a osadzi nimi wozy swoje, i poczyni je jezdnymi, a będą biegać przed wozem jego; Poczyni też sobie z nich pułkowniki nad tysiącami, i rotmistrze nad pięćdziesięcioma; poczyni z nich oracze ról swoich, i żeńce żniwa swego, i te, którzyby robili rynsztunki wojenne, i potrzeby do wozów jego. Córki też wasze pobierze, by gotowały rzeczy wonne, i były kucharkami i piekarkami. Pola też wasze, i winnice wasze, i oliwnice wasze co najlepsze pobierze, a rozda sługom swoim. Przytem z zasiewków waszych, i z winnic waszych będzie brał dziesięciny, i rozda je komornikom swoim, i sługom swoim. Także sługi wasze, i dziewki wasze, i młodzieńce wasze co najgrzeczniejsze będzie brał, i osły wasze pobierze, i obróci do roboty swojej. Z bydła waszego dziesięcinę będzie brał, a wy będziecie niewolnikami jego.', 'Samuel, prawo króla, rydwany, pobór, dziesięcina, militaryzm, niewola podatkowa', 'official_translation', 'draft', 'Biblia Gdańska (wyd. 1881, domena publiczna)', NULL, NULL, NULL, NULL, NULL, 'e2c393a7445ef2a2');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (16, 'en', 'Every gun that is made, every warship launched, every rocket fired signifies, in the final sense, a theft from those who hunger and are not fed, those who are cold and are not clothed. This world in arms is not spending money alone. It is spending the sweat of its laborers, the genius of its scientists, the hopes of its children.', 'Eisenhower, every gun is a theft, cross of iron, fertility of the plowshare, sterility of the sword, military spending, opportunity cost', 'official_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, '7e394f70fa42e41f');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (16, 'pl', 'Każda wyprodukowana broń, każdy zwodowany okręt wojenny, każda wystrzelona rakieta oznacza w ostatecznym rachunku kradzież dokonaną na tych, którzy głodują i nie są nakarmieni, którzy marzną i nie są przyodziani. Świat pod bronią nie wydaje jedynie pieniędzy. Wydaje pot swoich robotników, geniusz swoich naukowców i nadzieje swoich dzieci.', 'Eisenhower, każda broń to kradzież, krzyż z żelaza, płodność lemiesza, jałowość miecza, wydatki zbrojeniowe, koszt alternatywny', 'human_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, 'adff2bf014da48a0');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (17, 'en', 'Article I (1) For the purpose of the permanent maintenance of its external independence and for the purpose of the inviolability of its territory, Austria of its own free will declares herewith its permanent neutrality which it is resolved to maintain and defend with all the means at its disposal. (2) In order to secure these purposes Austria will never in the future accede to any military alliances nor permit the establishment of military bases of foreign States on its territory.', 'Austria 1955, perpetual neutrality, immerwährende Neutralität, foreign bases, military alliances, from pincer to bridge', 'official_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, '6ca00c8b257916db');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (17, 'pl', 'Art. I (1) W celu trwałego utrzymania swojej niezależności na zewnątrz oraz w celu zachowania nienaruszalności swojego terytorium, Austria oświadcza z własnej wolnej woli swoją wieczystą neutralność. Austria będzie ją utrzymywać i bronić jej wszystkimi dostępnymi środkami. (2) W celu zabezpieczenia tych celów Austria w przyszłości nie przystąpi do żadnych sojuszy wojskowych i nie dopuści do tworzenia na swoim terytorium baz wojskowych obcych państw.', 'Austria 1955, wieczysta neutralność, immerwährende Neutralität, obce bazy, sojusze wojskowe, z kleszczy w most', 'human_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, 'e6c67e3aa041f6b8');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (18, 'en', 'Constitution of Malta, Article 1(3): Malta is a neutral state actively pursuing peace, security and social progress among all nations by adhering to a policy of non-alignment and refusing to participate in any military alliance. Constitution of Costa Rica, Article 12: The Army as a permanent institution is abolished; for vigilance and the preservation of the public order, there will be the necessary police forces.', 'Malta Art. 1(3), Costa Rica Art. 12, constitutional neutrality, active pursuit of peace, non-alignment', 'official_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, '1bca42032ee563df');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (18, 'pl', 'Konstytucja Malty, Art. 1 ust. 3: Malta jest państwem neutralnym, aktywnie dążącym do pokoju, bezpieczeństwa i postępu społecznego wśród wszystkich narodów poprzez politykę niezaangażowania i odmowę udziału w jakimkolwiek sojuszu wojskowym. Konstytucja Kostaryki, Art. 12: Znosi się stałą armię jako instytucję państwową; dla czujności i zachowania porządku publicznego tworzy się niezbędne siły policyjne.', 'Malta Art. 1 ust. 3, Kostaryka Art. 12, konstytucyjna neutralność, aktywne dążenie do pokoju, obce bazy', 'human_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, '7026c001484a1934');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (19, 'en', 'The Plowshare Pact proclaims the "Oasis of Peace of Central Europe" Doctrine built on five pillars: (1) Sovereignty of Peace over Garrison Sovereignty — sovereignty is a means to protect Polish life and property, not a political fetish; (2) Fertility of the Plowshare over Sterility of the Sword — factories, farms, and families multiply national strength while credit-bought weaponry (without source codes) breeds debt; (3) Christian Royal Reckoning (Luke 14:31–32) over pagan Vegetius (Si vis pacem, para bellum); (4) Ending Risk Asymmetry (John 10:11–13) and any repeat of the 1939 Kuty bridge flight; (5) Constitutional Armed Territorial Neutrality (modeled on Switzerland, Austria 1955, and Malta Art. 1(3)). In debate we reject Hegelian dialectics (thesis–antithesis–synthesis) in favor of Thomistic Disputation and Chivalrous, Principled Polemics.', 'Plowshare Pact, Oasis of Peace, sovereignty of peace, fertility of the plowshare, royal reckoning, Thomistic disputation, chivalrous polemics, anti-Hegelian', 'official_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, 'c6d01b6b22c17330');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (19, 'pl', 'Przymierze Lemiesza głosi Doktrynę „Oazy Pokoju Europy Środkowej” opartą na pięciu filarach: (1) Suwerenność Pokoju zamiast Suwerenności Garnizonu — suwerenność to środek do ochrony życia i własności Polaków, a nie fetysz polityczny; (2) Płodność Lemiesza ponad Jałowością Miecza — fabryka, rola i rodzina pomnażają siłę narodu, podczas gdy zbrojenia na kredyt (bez kodów źródłowych) rodzą dług; (3) Chrześcijański Rachunek Królewski (Łk 14, 31–32) ponad pogańskim Wegecjuszem (Si vis pacem, para bellum); (4) Koniec Asymetrii Ryzyka (J 10, 11–13) i powtórki z mostu w Kutach 1939 r.; (5) Konstytucyjna Zbrojna Neutralność Terytorialna (wzór Szwajcarii, Austrii 1955 i Malty Art. 1 ust. 3). W debacie odrzucamy dialektykę heglowską (teza–antyteza–synteza) na rzecz Dysputy Tomistycznej i Rycerskiej, Pryncypialnej Polemiki.', 'Przymierze Lemiesza, Oaza Pokoju, suwerenność pokoju, płodność lemiesza, rachunek królewski, dysputa tomistyczna, rycerska polemika, odrzucenie heglizmu', 'original', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, '9856493831718c14');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (20, 'en', 'Paraphrase of the NATO Partnership for Peace dossier on Austria (updated 9 Dec 2025): cooperation is conducted via PfP (1995), EAPC (1997), and ITPP; the Planning and Review Process (PARP) influences Austrian planning activities; and any deployment of Austrian units for PfP operations must be authorised case-by-case by the Austrian Council of Ministers and approved by the Main Committee of the Austrian Parliament.', 'NATO, Austria, Partnership for Peace, PfP, PARP, ITPP, Austrian Parliament, Main Committee', 'paraphrase', 'human_approved', NULL, NULL, NULL, NULL, NULL, NULL, '570a7fe995eebe33');
INSERT INTO source_texts (source_id, locale, text, keywords, origin, review, translator, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash) VALUES (20, 'pl', 'Parafraza oficjalnego biuletynu NATO o relacjach z Austrią (aktualizacja z 9 XII 2025 r.): współpraca przebiega w ramach Partnerstwa dla Pokoju (PfP, 1995), Rady Partnerstwa Euroatlantyckiego (EAPC, 1997) oraz Indywidualnie Dostosowanego Programu Partnerstwa (ITPP); Proces Planowania i Oceny (PARP) wpływa na austriackie planowanie obronne, przy czym każdorazowe wysłanie austriackich jednostek do operacji PfP musi zostać autoryzowane przez Radę Ministrów i zatwierdzone przez Komisję Główną Parlamentu Austrii.', 'NATO, Austria, Partnerstwo dla Pokoju, PfP, PARP, ITPP, Parlament Austrii, Komisja Główna', 'paraphrase', 'human_approved', NULL, NULL, NULL, NULL, NULL, NULL, '56ab7cb2f89d7760');

-- arguments: 9 row(s)
INSERT INTO arguments (id, fallacy_type, core_principle, tags, updated_by, updated_at) VALUES (1, 'false_dichotomy', 'Suwerenność Pokoju ponad Suwerennością Garnizonu (Wzór, nie Kopia)', 'neutralność, suwerenność, Szwajcaria, Austria 1955, kleszcze geopolityczne, Korona', 'seed', '2026-10-16 00:57:32');
INSERT INTO arguments (id, fallacy_type, core_principle, tags, updated_by, updated_at) VALUES (2, 'utopian_militarism', 'Rachunek Królewski (Łk 14, 31–32) oraz realizm demograficzno-gospodarczy', 'Polska-Sparta, demografia, gospodarka, kredyt, kody źródłowe, Łk 14, Korona', 'seed', '2026-10-16 00:57:32');
INSERT INTO arguments (id, fallacy_type, core_principle, tags, updated_by, updated_at) VALUES (3, 'pagan_maxim_appeal', 'Chrystus (Łk 14, 31–32) ponad pogańskim Wegecjuszem (Si vis pacem, para bellum)', 'Si vis pacem para bellum, Wegecjusz, Łk 14, Pacem in Terris, wyścig zbrojeń, Korona', 'seed', '2026-10-16 00:57:32');
INSERT INTO arguments (id, fallacy_type, core_principle, tags, updated_by, updated_at) VALUES (4, 'historical_amnesia', 'Lekcja Sanacji 1939 i Koniec Asymetrii Ryzyka (J 10, 11–13)', 'Sanacja, 1939, most w Kutach, najemnik, dobry pasterz, traktaty, J 10, Korona', 'seed', '2026-10-16 00:57:32');
INSERT INTO arguments (id, fallacy_type, core_principle, tags, updated_by, updated_at) VALUES (5, 'fatalism', 'Geopolityka Teorii Gier zamiast Litości Sąsiadów', 'Austria 1955, teoria gier, strefa buforowa, Malta, neutralność, Korona', 'seed', '2026-10-16 00:57:32');
INSERT INTO arguments (id, fallacy_type, core_principle, tags, updated_by, updated_at) VALUES (6, 'broken_window_militarism', 'Płodność Lemiesza ponad Jałowością Miecza (Eisenhower 1953 / 1 Sm 8)', 'ekonomia, lemiesz a miecz, Eisenhower, Samuel, Bastiat, budżet, Korona', 'seed', '2026-10-16 00:57:32');
INSERT INTO arguments (id, fallacy_type, core_principle, tags, updated_by, updated_at) VALUES (7, 'strawman', 'Distinguo Tomistyczne: Oaza Pokoju (Zbrojna Neutralność Terytorialna) to nie Oaza Bezbronności', 'Oaza Pokoju, Oaza Bezbronności, obrona terytorialna, Gaudium et Spes, Lubmin, Korona', 'seed', '2026-10-16 00:57:32');
INSERT INTO arguments (id, fallacy_type, core_principle, tags, updated_by, updated_at) VALUES (8, 'hegelian_relativism', 'Odrzucenie Dialektyki Heglowskiej na rzecz Dysputy Tomistycznej i Rycerskiej Polemiki', 'Hegel, dialektyka, dysputa tomistyczna, rycerska polemika, metodologia, prawda', 'seed', '2026-10-16 00:57:32');
INSERT INTO arguments (id, fallacy_type, core_principle, tags, updated_by, updated_at) VALUES (9, 'false_dilemma', 'Doktryna Jeża i Teoria Gier: Neutralność Zbrojna to asymetryczny koszt inwazji przewyższający zysk agresora', 'doktryna jeża, teoria gier, Szwajcaria, neutralność zbrojna, obrona terytorialna, asymetria, Hitler, Korona', 'seed', '2026-10-16 06:14:36');

-- argument_texts: 18 row(s)
INSERT INTO argument_texts (argument_id, locale, opponent_claim, counter_punch, keywords, origin, review, supporting_spans_json, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash, audited_at) VALUES (1, 'en', 'Switzerland is Switzerland, while Poland lies between great powers in a geopolitical pincer — we do not need a neutral Poland, we need a sovereign Poland.', 'Pitting sovereignty against neutrality is a false dichotomy, and arguing "Poland has no Alps" attacks a strawman — Switzerland is our model of state philosophy, not a mechanical copy of geography. In 1955 Austria lay in the flatlands at the epicenter of the Cold War under four-power occupation, yet by constitutional law it chose perpetual neutrality: "Austria of its own free will declares herewith its permanent neutrality". Precisely because Poland lies between great powers, the only way to escape the geopolitical pincer is to become a neutral bridge protected by international law ("The territory of neutral Powers is inviolable") rather than a frontline garrison.', 'Switzerland, sovereignty, neutrality, geopolitical pincer, model not copy, Austria 1955', 'human_translation', 'draft', '[{"source_id":17,"span":"Austria of its own free will declares herewith its permanent neutrality"}]', NULL, NULL, NULL, NULL, NULL, '7f2a942f7a38a303', NULL);
INSERT INTO argument_texts (argument_id, locale, opponent_claim, counter_punch, keywords, origin, review, supporting_spans_json, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash, audited_at) VALUES (1, 'pl', 'Szwajcaria to Szwajcaria, a Polska leży między mocarstwami w kleszczach geopolitycznych — nie potrzebujemy Polski neutralnej, potrzebujemy Polski suwerennej.', 'Przeciwstawianie suwerenności i neutralności to fałszywa dychotomia, a zarzut „Polska nie ma Alp” bije w chochoła — Szwajcaria jest dla nas wzorem filozofii państwa, nie mechaniczną kopią geografii. Austria w 1955 r. leżała na nizinie w samym epicentrum zimnej wojny i była okupowana przez cztery mocarstwa, a jednak ustawą konstytucyjną wybrała wieczystą neutralność: „Austria oświadcza z własnej wolnej woli swoją wieczystą neutralność”. Właśnie dlatego, że Polska leży między mocarstwami, jedynym sposobem na wyjęcie jej z geopolitycznych kleszczy jest przekształcenie jej w neutralny most chroniony prawem międzynarodowym („Terytorium mocarstw neutralnych jest nienaruszalne”), zamiast skazywania jej na rolę przedmurza i poligonu.', 'Szwajcaria, suwerenność, neutralność, kleszcze geopolityczne, wzór nie kopia, Austria 1955', 'original', 'draft', '[{"source_id":17,"span":"Austria oświadcza z własnej wolnej woli swoją wieczystą neutralność"}]', NULL, NULL, NULL, NULL, NULL, '7f2a942f7a38a303', NULL);
INSERT INTO argument_texts (argument_id, locale, opponent_claim, counter_punch, keywords, origin, review, supporting_spans_json, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash, audited_at) VALUES (2, 'en', 'Poland must be one of the strongest military powers in Europe, or else she will be dependent on others and reduced to a pawn.', 'The vision of a "Poland-Sparta" challenging great powers with a 1.16 fertility rate and an economy six times smaller than Germany’s ignores Christ’s Royal Reckoning in Luke 14: a king with ten thousand facing twenty thousand "sends a delegation and asks for terms of peace". Furthermore, an army bought on massive credit from the US and South Korea without source codes or domestic supply chains does not create sovereignty — it turns Poland into an indebted client of foreign defense contractors.', 'Poland-Sparta, military power, demography, royal reckoning, Luke 14, source codes, credit', 'human_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, 'e3b0c44298fc1c14', NULL);
INSERT INTO argument_texts (argument_id, locale, opponent_claim, counter_punch, keywords, origin, review, supporting_spans_json, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash, audited_at) VALUES (2, 'pl', 'Polska musi być jednym z najsilniejszych militarnie państw w Europie, albo będzie zależna od innych i stanie się pionkiem.', 'Wizja „Polski-Sparty” rzucającej militarne wyzwanie mocarstwom przy dzietności 1,16 i gospodarce sześciokrotnie mniejszej od niemieckiej ignoruje Chrześcijański Rachunek Królewski z Ewangelii św. Łukasza: król mający dziesięć tysięcy żołnierzy przeciw dwudziestu tysiącom „wyprawia poselstwo, gdy tamten jest jeszcze daleko, i prosi o warunki pokoju”. Co więcej, armia kupowana na gigantyczny kredyt w USA i Korei Południowej bez kodów źródłowych i łańcuchów dostaw nie daje suwerenności — zamienia Polskę w zadłużonego klienta obcych zbrojeniówek.', 'Polska-Sparta, mocarstwo militarne, demografia, rachunek królewski, Łk 14, kody źródłowe, kredyt', 'original', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, 'e3b0c44298fc1c14', NULL);
INSERT INTO argument_texts (argument_id, locale, opponent_claim, counter_punch, keywords, origin, review, supporting_spans_json, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash, audited_at) VALUES (3, 'en', 'The maxim "if you want peace, prepare for war" (Si vis pacem, para bellum) remains valid — peace is preserved solely by deterrence and rearmament.', 'The maxim "Si vis pacem, para bellum" comes neither from the Gospel nor from the Church’s Magisterium, but from the 4th-century pagan Roman writer Vegetius — and the Rome that trusted it bankrupted itself under military outlays and collapsed, just as Europe did in 1914. Catholic political realism places higher Christ’s words in Luke 14:31–32 ("sends a delegation and asks for terms of peace") and St. John XXIII’s teaching in Pacem in Terris §112: "justice, right reason, and the recognition of man''s dignity cry out insistently for a cessation to the arms race."', 'Si vis pacem para bellum, Vegetius, deterrence, arms race, Pacem in Terris, Luke 14', 'human_translation', 'draft', '[{"source_id":1,"span":"justice, right reason, and the recognition of man''s dignity cry out insistently for a cessation to the arms race"}]', NULL, NULL, NULL, NULL, NULL, '0a8ef3e83ed72b93', NULL);
INSERT INTO argument_texts (argument_id, locale, opponent_claim, counter_punch, keywords, origin, review, supporting_spans_json, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash, audited_at) VALUES (3, 'pl', 'Zasada „chcesz pokoju, szykuj się do wojny” (Si vis pacem, para bellum) pozostaje aktualna — pokój utrzymuje się wyłącznie odstraszaniem i zbrojeniami.', 'Maksyma „Si vis pacem, para bellum” nie pochodzi z Ewangelii ani z Magisterium Kościoła, lecz od pogańskiego pisarza rzymskiego Wegecjusza z IV wieku — a Rzym, który jej zaufał, zbankrutował pod ciężarem wydatków wojskowych i upadł, podobnie jak Europa w 1914 roku. Katolicki realizm polityczny stawia wyżej słowa Chrystusa z Łk 14, 31–32 („wyprawia poselstwo, gdy tamten jest jeszcze daleko, i prosi o warunki pokoju”) oraz nauczanie św. Jana XXIII w Pacem in Terris §112: „sprawiedliwość, prawy rozum i poczucie godności ludzkiej domagają się usilnie zaprzestania wyścigu zbrojeń”.', 'Si vis pacem para bellum, Wegecjusz, odstraszanie, wyścig zbrojeń, Pacem in Terris, Łk 14', 'original', 'draft', '[{"source_id":1,"span":"sprawiedliwość, prawy rozum i poczucie godności ludzkiej domagają się usilnie zaprzestania wyścigu zbrojeń"}]', NULL, NULL, NULL, NULL, NULL, '0a8ef3e83ed72b93', NULL);
INSERT INTO argument_texts (argument_id, locale, opponent_claim, counter_punch, keywords, origin, review, supporting_spans_json, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash, audited_at) VALUES (4, 'en', 'In 1939 Poland had non-aggression pacts and allied guarantees, yet they failed to save us from catastrophe — paper declarations mean nothing.', 'The catastrophe of September 1939 was the bankruptcy of the Sanacja model of "great-power posturing on feet of clay": throughout the 1930s Sanacja spent 35% to 50% of the state budget on the military while rural families split matches in four, rejecting neutrality in favor of entanglement in great-power alliances. When tested, that military edifice collapsed in days, and the authors of "not giving up a single button" crossed the bridge at Kuty on September 17, fulfilling the Gospel image of the hireling who "sees the wolf coming and leaves the sheep and flees" (John 10:12). The Plowshare Pact proposes not paper war alliances, but constitutional neutrality (like Malta Art. 1(3)) paired with elite accountability.', '1939, Sanacja, Kuty bridge, treaties, guarantees, hireling, John 10, risk asymmetry', 'human_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, 'e3b0c44298fc1c14', NULL);
INSERT INTO argument_texts (argument_id, locale, opponent_claim, counter_punch, keywords, origin, review, supporting_spans_json, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash, audited_at) VALUES (4, 'pl', 'W 1939 roku Polska miała traktaty o nieagresji i gwarancje sojusznicze, a mimo to nie uchroniły nas one przed katastrofą — papierowe deklaracje nic nie znaczą.', 'Katastrofa września 1939 r. była bankructwem właśnie sanacyjnego modelu „mocarstwowości na glinianych nogach”: w latach 30. Sanacja wydawała od 35% do 50% budżetu państwa na wojsko kosztem skrajnej nędzy wsi dzielącej zapałkę na czworo, odrzucając neutralność na rzecz egzotycznych sojuszy zaczepnych. Gdy przyszła próba, ten gigantyczny wysiłek zbrojny załamał się w kilkanaście dni, a autorzy haseł o „nieoddawaniu nawet guzika” już 17 września przekraczali most w Kutach, wypełniając ewangeliczny obraz najemnika: „widząc nadchodzącego wilka, opuszcza owce i ucieka” (J 10, 12). Pakt Lemiesza proponuje nie papierowe sojusze wojenne, lecz konstytucyjną neutralność (jak Malta Art. 1 ust. 3) połączoną z końcem bezkarności polityków.', '1939, Sanacja, most w Kutach, traktaty, gwarancje, najemnik, J 10, asymetria ryzyka', 'original', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, 'e3b0c44298fc1c14', NULL);
INSERT INTO argument_texts (argument_id, locale, opponent_claim, counter_punch, keywords, origin, review, supporting_spans_json, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash, audited_at) VALUES (5, 'en', 'Austria achieved neutrality in 1955 only because the great powers agreed to it — today no one will gift us neutrality out of goodwill.', 'Neutrality never rests on the "mercy" or "goodwill" of great powers, but on hard game theory and cost-benefit calculation. In 1955 neither the USA nor the USSR acted out of sentiment toward Vienna — both recognized that a predictable buffer in Central Europe where "Austria will never in the future accede to any military alliances nor permit the establishment of military bases of foreign States on its territory" was cheaper and safer for both blocs than direct confrontation. Yet the powers did not invent that offer on their own: Chancellor Julius Raab and the Austrian nation had to put it on the table first, just as Malta enshrined neutrality in Article 1(3) of its Constitution.', 'Austria 1955, great power consensus, game theory, buffer state, Julius Raab, Malta Art. 1', 'human_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, 'e3b0c44298fc1c14', NULL);
INSERT INTO argument_texts (argument_id, locale, opponent_claim, counter_punch, keywords, origin, review, supporting_spans_json, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash, audited_at) VALUES (5, 'pl', 'Austria uzyskała neutralność w 1955 roku tylko dlatego, że zgodziły się na to wielkie mocarstwa — dziś nikt nam neutralności z dobrej woli nie podaruje.', 'Neutralność nigdy nie opiera się na „litości” ani „dobrej woli” mocarstw, lecz na twardej teorii gier i rachunku zysków i strat. W 1955 r. ani USA, ani ZSRR nie kierowały się sentymentem do Wiednia — uznały, że przewidywalny bufor w sercu Europy, w którym „Austria w przyszłości nie przystąpi do żadnych sojuszy wojskowych i nie dopuści do tworzenia na swoim terytorium baz wojskowych obcych państw”, jest dla obu bloków tańszy i bezpieczniejszy niż bezpośrednie zwarcie. Ale mocarstwa nie złożyły tej oferty same z siebie: najpierw rząd Juliusa Raaba i naród austriacki musieli położyć tę ofertę na stole, dokładnie jak Malta w Art. 1 ust. 3 Konstytucji.', 'Austria 1955, zgoda mocarstw, teoria gier, strefa buforowa, Julius Raab, Malta Art. 1', 'original', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, 'e3b0c44298fc1c14', NULL);
INSERT INTO argument_texts (argument_id, locale, opponent_claim, counter_punch, keywords, origin, review, supporting_spans_json, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash, audited_at) VALUES (6, 'en', 'A modern army drives advanced technology and industry — peace, a strong economy, and a massive army do not exclude one another, so there is no need to choose between the plowshare and the sword.', 'Economics is governed by the hard law of scarcity: every zloty, every engineer, and every demographic cohort diverted into credit-financed armaments is taken from Polish families, infrastructure, and civilian enterprise. As General Dwight D. Eisenhower warned: "Every gun that is made, every warship launched, every rocket fired signifies, in the final sense, a theft from those who hunger and are not fed". The plowshare (factory, farm, family) is fertile and self-financing; the sword (imported combat hardware rusting in depots) is economically sterile and fulfills the Prophet Samuel’s warning against the militarist state (1 Samuel 8:11–17).', 'plowshare vs sword, Eisenhower, Samuel, opportunity cost, fertility of the plowshare, sterility of the sword, economy', 'human_translation', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, 'e3b0c44298fc1c14', NULL);
INSERT INTO argument_texts (argument_id, locale, opponent_claim, counter_punch, keywords, origin, review, supporting_spans_json, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash, audited_at) VALUES (6, 'pl', 'Nowoczesna armia to zaawansowane technologie i impuls dla przemysłu — pokój, silna gospodarka i wielka armia nie wykluczają się, więc nie trzeba wybierać między lemieszem a mieczem.', 'Ekonomia zna twarde prawo rzadkości zasobów: każda złotówka, każdy inżynier i każdy rocznik demograficzny skierowany do zbrojeń na kredyt jest odebrany polskiej rodzinie, infrastrukturze i cywilnej przedsiębiorczości. Jak ostrzegał gen. Dwight D. Eisenhower: „Każda wyprodukowana broń, każdy zwodowany okręt wojenny, każda wystrzelona rakieta oznacza w ostatecznym rachunku kradzież dokonaną na tych, którzy głodują i nie są nakarmieni”. Lemiesz (fabryka, rola, rodzina) jest płodny i sam się finansuje; miecz (importowany sprzęt bojowy rdzewiejący w magazynach) jest ekonomicznie jałowy i spełnia przestrogę proroka Samuela o państwie militarnym (1 Sm 8, 11–17).', 'lemiesz a miecz, Eisenhower, Samuel, koszt alternatywny, płodność lemiesza, jałowość miecza, gospodarka', 'original', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, 'e3b0c44298fc1c14', NULL);
INSERT INTO argument_texts (argument_id, locale, opponent_claim, counter_punch, keywords, origin, review, supporting_spans_json, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash, audited_at) VALUES (7, 'en', 'The slogan "Poland as an Oasis of Peace" sounds like an "Oasis of Defenselessness" and naive pacifism — only a strong country with a mighty army can preserve peace.', 'Applying the classical Thomistic distinction (Distinguo): the Plowshare Pact has never preached an "Oasis of Defenselessness", but the "Oasis of Peace of Central Europe" Doctrine grounded in Constitutional Armed Territorial Neutrality (modeled on Switzerland, Austria 1955, and Malta Art. 1(3)). In line with Gaudium et Spes §79, "governments cannot be denied the right to legitimate defense once every means of peaceful settlement has been exhausted." What we reject is not defending our home, but credit-financed long-range strike weapons, foreign military bases, and pushing Poland into proxy wars — echoing the Lubmin declaration: "There cannot be prosperity without peace. We are not warmongers."', 'Oasis of Peace, Oasis of Defenselessness, pacifism, territorial defense, Gaudium et Spes, Lubmin, Distinguo', 'human_translation', 'draft', '[{"source_id":4,"span":"governments cannot be denied the right to legitimate defense once every means of peaceful settlement has been exhausted"}]', NULL, NULL, NULL, NULL, NULL, 'c32839f8b6257ad7', NULL);
INSERT INTO argument_texts (argument_id, locale, opponent_claim, counter_punch, keywords, origin, review, supporting_spans_json, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash, audited_at) VALUES (7, 'pl', 'Hasło „Polska Oazą Pokoju” brzmi jak „Oaza Bezbronności” i naiwny pacyfizm — tylko silny kraj z potężną armią może zachować pokój.', 'Zastosujmy klasyczne rozróżnienie tomistyczne (Distinguo): Pakt Lemiesza nigdy nie głosił „Oazy Bezbronności”, lecz „Doktrynę Oazy Pokoju Europy Środkowej” opartą na Konstytucyjnej Zbrojnej Neutralności Terytorialnej (wzór Szwajcarii, Austrii 1955 i Malty Art. 1 ust. 3). Zgodnie z Gaudium et Spes §79 „nie można odmawiać rządom prawa do koniecznej obrony, byle wyczerpały wpierw wszystkie środki pokojowych rokowań”. Odrzucamy nie obronę własnego domu, lecz broń dalekiego zasięgu kupowaną na kredyt, obce bazy wojskowe i ekspedycyjne wpychanie Polski w cudze wojny — w pełnej zgodzie ze słowami z Lubmina: „Nie może być dobrobytu bez pokoju. Nie jesteśmy podżegaczami wojennymi”.', 'Oaza Pokoju, Oaza Bezbronności, pacyfizm, obrona terytorialna, Gaudium et Spes, Lubmin, Distinguo', 'original', 'draft', '[{"source_id":4,"span":"nie można odmawiać rządom prawa do koniecznej obrony, byle wyczerpały wpierw wszystkie środki pokojowych rokowań"}]', NULL, NULL, NULL, NULL, NULL, 'c32839f8b6257ad7', NULL);
INSERT INTO argument_texts (argument_id, locale, opponent_claim, counter_punch, keywords, origin, review, supporting_spans_json, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash, audited_at) VALUES (8, 'en', 'In the dispute between advocates of militarization and advocates of neutrality, we should apply dialectical synthesis and find a middle-ground compromise.', 'In debate we reject Hegelian dialectics (thesis–antithesis–synthesis) in favor of Thomistic Disputation and Chivalrous, Principled Polemics. Hegelian dialectics dissolves objective truth into relativistic compromise, whereas peace "is rightly and appropriately called an enterprise of justice" (Gaudium et Spes §78). In the spirit of St. Thomas Aquinas, we state the opponent’s strongest argument with complete fairness (Videtur quod) and answer it with unchanging moral principle, natural law, and verifiable historical evidence (Respondeo / Ad argumenta).', 'Hegel, Hegelian dialectics, Thomistic disputation, chivalrous polemics, synthesis, objective truth', 'human_translation', 'draft', '[{"source_id":19,"span":"In debate we reject Hegelian dialectics (thesis–antithesis–synthesis) in favor of Thomistic Disputation and Chivalrous, Principled Polemics"}]', NULL, NULL, NULL, NULL, NULL, '16f7924b9701532a', NULL);
INSERT INTO argument_texts (argument_id, locale, opponent_claim, counter_punch, keywords, origin, review, supporting_spans_json, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash, audited_at) VALUES (8, 'pl', 'W sporze między zwolennikami militaryzacji a zwolennikami neutralności trzeba zastosować dialektyczną syntezę i znaleźć kompromis pośrodku.', 'W debacie odrzucamy dialektykę heglowską (teza–antyteza–synteza) na rzecz Dysputy Tomistycznej i Rycerskiej, Pryncypialnej Polemiki. Heglowska dialektyka rozmywa prawdę obiektywną w relatywistycznym kompromisie, podczas gdy pokój „słusznie i właściwie zowie się dziełem sprawiedliwości” (Gaudium et Spes §78). W duchu św. Tomasza z Akwinu uczciwie przytaczamy najmocniejszą postać argumentu adwersarza (Videtur quod), po czym odpowiadamy nań niezmienną zasadą moralną, prawem naturalnym i weryfikowalnym dowodem historycznym (Respondeo / Ad argumenta).', 'Hegel, dialektyka heglowska, dysputa tomistyczna, rycerska polemika, synteza, prawda obiektywna', 'original', 'draft', '[{"source_id":19,"span":"W debacie odrzucamy dialektykę heglowską (teza–antyteza–synteza) na rzecz Dysputy Tomistycznej i Rycerskiej, Pryncypialnej Polemiki"}]', NULL, NULL, NULL, NULL, NULL, '16f7924b9701532a', NULL);
INSERT INTO argument_texts (argument_id, locale, opponent_claim, counter_punch, keywords, origin, review, supporting_spans_json, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash, audited_at) VALUES (9, 'en', 'Neutrality relies on the goodwill of neighbors, and caught between Russia and Germany that is naive and leaves us at the mercy of enemies — without a massive army they will crush us.', 'Neutrality does not depend on a neighbor’s altruism or goodwill, but on cold game theory and cost-benefit reckoning. Switzerland did not survive World War II because Hitler felt "goodwill" toward it — Hitler despised the Swiss. It survived because its asymmetric defense (the hedgehog doctrine: widespread territorial defense, defensive saturation, and readiness to destroy Alpine tunnels) and its role as a neutral trade and financial hub made invasion simply unprofitable compared to respecting its status. Swallowing the hedgehog costs far more blood and treasure than any aggressor could gain.', 'hedgehog doctrine, game theory, Switzerland, armed neutrality, territorial defense, cost-benefit, asymmetry', 'human_translation', 'draft', '[{"source_id":19,"span":"asymmetric cost of invasion exceeding aggressor gains, saturating territory with civil defense and drones"}]', NULL, NULL, NULL, NULL, NULL, '1b44cfb9c0db3045', NULL);
INSERT INTO argument_texts (argument_id, locale, opponent_claim, counter_punch, keywords, origin, review, supporting_spans_json, audit_json, audit_notes, drafter_model, auditor_model, prompt_version, source_hash, audited_at) VALUES (9, 'pl', 'Neutralność wymaga dobrej woli sąsiadów, a w kleszczach między Rosją a Niemcami to naiwność i zdanie się na łaskę wroga — bez potężnej armii nas rozjadą.', 'Neutralność nie opiera się na altruizmie ani dobrej woli sąsiada, lecz na chłodnej teorii gier i bilansie zysków i strat. Szwajcaria nie przetrwała II wojny światowej dlatego, że Hitler miał wobec niej „dobrą wolę” – Hitler gardził Szwajcarami. Przetrwała, ponieważ jej asymetryczna obrona (doktryna jeża: powszechna obrona terytorialna, nasycenie terenu bronią defensywną i gotowość wysadzenia tuneli alpejskich) oraz status neutralnego węzła finansowego sprawiły, że inwazja była dla Rzeszy po prostu mniej opłacalna niż uszanowanie jej statusu. Połknięcie jeża kosztuje zbyt wiele krwi i kapitału, by agresja miała sens.', 'doktryna jeża, teoria gier, Szwajcaria, neutralność zbrojna, Hitler, obrona terytorialna, zysk i strata, asymetria', 'original', 'draft', '[{"source_id":19,"span":"asymetryczny koszt inwazji przewyższający zysk agresora, nasycenie terenu obroną cywilną i dronami"}]', NULL, NULL, NULL, NULL, NULL, '1b44cfb9c0db3045', NULL);

