INSERT INTO media_assets (id, slug, title, artist_or_author, media_type, genre, mood, target_audience, platform, external_id, url, embed_url, duration_seconds, language, ai_assisted, production_credits, lyrics_or_transcript, lyrics_license, lyrics_cleared_to_store, notes, status, reviewed_by, reviewed_at, created_by, created_at, updated_at, public_note, archive_url, link_checked_at, link_status) VALUES (3, 'korowod-marek-grechuta', 'Korowód', 'Marek Grechuta & Anawa', 'music', 'patriotic_folk', NULL, NULL, 'youtube', 'vrZKEvEen0M', 'https://www.youtube.com/watch?v=vrZKEvEen0M', 'https://www.youtube-nocookie.com/embed/vrZKEvEen0M', NULL, NULL, 0, NULL, 'Kto pierwszy szedł przed siebie?
Kto pierwszy cel wyznaczył?
Kto pierwszy w nas rozpoznał?
Kto wrogów? Kto przyjaciół?
Kto pierwszy sławę wszelką
I włości swe miał za nic?
