-- campaign_posters: 16 row(s)
INSERT INTO campaign_posters (id, slug, title, artist_or_author, image_path, theme, caption_pl, caption_en, symbolism_notes, ai_assisted, production_credits, status, reviewed_by, reviewed_at, created_by, created_at, updated_at, series_slug, series_order, is_planet, layer, pair_key, moral_quote_pl, moral_quote_en, alt_pl, alt_en, license, origin, width, height) VALUES (1, 'dwie-korony-chrystus-krol-pokoju-ponad-korona-politycznego-militaryzmu', 'Dwie Korony — Chrystus Król Pokoju ponad Koroną Politycznego Militaryzmu', 'Pakt Lemiesza Studio', '/images/two_crowns_hero.jpg', 'sovereignty_peace', 'Chrystusowy Rachunek Królewski (Łk 14, 31–32) i Korona Pokoju ponad iluzją „Polski-Sparty” oraz pogańską maksymą Wegecjusza.', 'Christ’s Royal Reckoning (Luke 14:31–32) and the Crown of Peace above the illusion of "Poland-Sparta" and pagan Vegetian militarism.', 'Zestawienie dwóch koron: prawdziwej suwerenności zakorzenionej w Ładzie Bożym i Oazie Pokoju wobec upaństwowionego kultu garnizonu.', 1, 'Koncept: Bogdan Zięba (Pakt Lemiesza); opracowanie graficzne wspomagane AI (static/images/two_crowns_hero.jpg).', 'draft', NULL, NULL, 'seed', '2026-10-16 00:57:32', '2026-10-16 00:57:32', NULL, 0, 0, 'standalone', NULL, NULL, NULL, NULL, NULL, NULL, 'static', NULL, NULL);
INSERT INTO campaign_posters (id, slug, title, artist_or_author, image_path, theme, caption_pl, caption_en, symbolism_notes, ai_assisted, production_credits, status, reviewed_by, reviewed_at, created_by, created_at, updated_at, series_slug, series_order, is_planet, layer, pair_key, moral_quote_pl, moral_quote_en, alt_pl, alt_en, license, origin, width, height) VALUES (2, 'swietosc-zwyklego-zycia-plodnosc-lemiesza-ponad-jalowoscia-miecza', 'Świętość Zwykłego Życia — Płodność Lemiesza ponad Jałowością Miecza', 'Pakt Lemiesza Studio', '/images/kaszanka_sacred_life.jpg', 'sacred_life', 'Polski stół, chleb, praca i rodzina: państwo istnieje po to, by chronić świętość zwykłego życia, a nie spalać owoce pracy narodu w cudzych wojnach.', 'The Polish table, bread, labor, and family: the state exists to guard the sanctity of ordinary life, not to burn the fruits of national labor in proxy wars.', 'Symbol Płodności Lemiesza (Iz 2, 4; Eisenhower 1953) oraz sprzeciwu wobec Asymetrii Ryzyka (J 10, 11–13), w której elity uciekają przez most w Kutach, a koszt wojny ponosi zwykły człowiek.', 1, 'Koncept: Bogdan Zięba (Pakt Lemiesza); opracowanie graficzne wspomagane AI (static/images/kaszanka_sacred_life.jpg).', 'draft', NULL, NULL, 'seed', '2026-10-16 00:57:32', '2026-10-16 00:57:32', NULL, 0, 0, 'standalone', NULL, NULL, NULL, NULL, NULL, NULL, 'static', NULL, NULL);
INSERT INTO campaign_posters (id, slug, title, artist_or_author, image_path, theme, caption_pl, caption_en, symbolism_notes, ai_assisted, production_credits, status, reviewed_by, reviewed_at, created_by, created_at, updated_at, series_slug, series_order, is_planet, layer, pair_key, moral_quote_pl, moral_quote_en, alt_pl, alt_en, license, origin, width, height) VALUES (3, 'doktryna-jeza-oaza-pokoju-i-niestrawnosc-terytorialna', 'Doktryna Jeża — Oaza Pokoju i Niestrawność Terytorialna', 'Przymierze Lemiesza Studio (malarstwo olejne, styl Józefa Chełmońskiego)', '/images/doktryna-jeza/hedgehog_planet_hero.jpg', 'sovereignty_peace', 'Doktryna Jeża (Canon 04): Odstraszanie asymetryczne, zbrojna neutralność i suwerenność Rzeczypospolitej.', 'The Hedgehog Doctrine (Canon 04): Asymmetric deterrence, armed neutrality, and Polish sovereignty.', 'Nadrzędny obraz-planeta: najeżony, stalowy jeż w polskim krajobrazie, którego żaden imperialny drapieżnik nie jest w stanie połknąć.', 1, 'Koncept: Bogdan Zięba (Przymierze Lemiesza); obraz olejny w stylu polskiego realizmu XIX w. (Józef Chełmoński) wspomagany AI (static/images/doktryna-jeza/hedgehog_planet_hero.jpg).', 'draft', NULL, NULL, 'seed:series-corpus', '2026-10-16 07:21:09', '2026-10-16 07:21:09', 'doktryna-jeza', 0, 1, 'standalone', NULL, 'Nie jesteśmy drapieżnikiem, by napadać innych; jesteśmy jeżem, którego nikt nie zdoła połknąć.', 'We are not a predator to attack others; we are a hedgehog that no one can swallow.', NULL, NULL, NULL, 'static', NULL, NULL);
INSERT INTO campaign_posters (id, slug, title, artist_or_author, image_path, theme, caption_pl, caption_en, symbolism_notes, ai_assisted, production_credits, status, reviewed_by, reviewed_at, created_by, created_at, updated_at, series_slug, series_order, is_planet, layer, pair_key, moral_quote_pl, moral_quote_en, alt_pl, alt_en, license, origin, width, height) VALUES (4, 'jez-gospodarz-pod-debem-krok-1-alegoria', 'Jeż Gospodarz pod Dębem (Krok 1: Alegoria)', 'Przymierze Lemiesza Studio', '/images/doktryna-jeza/hedgehog_allegory_01.svg', 'agrarian_ethos', 'Jeż gospodarz dbający o swoje gniazdo i gromadzący zapasy przed zimą pod korzeniami dębu.', 'The hedgehog steward tending to its nest and gathering supplies beneath the roots of the oak.', 'Alegoria pracy organicznej: dbałość o własne obejście zamiast szukania zwady z obcymi bestiami.', 1, 'Przymierze Lemiesza Studio · SVG Design Canon 04', 'draft', NULL, NULL, 'seed:series-corpus', '2026-10-16 07:21:09', '2026-10-16 07:21:09', 'doktryna-jeza', 1, 0, 'allegory', 'step_1_work', 'Zanim zaczniesz machać szabelką, upewnij się, że masz co do garnka włożyć i czym dom ogrzać.', 'Before you draw your saber, ensure you have food in your pot and warmth in your home.', NULL, NULL, NULL, 'static', NULL, NULL);
INSERT INTO campaign_posters (id, slug, title, artist_or_author, image_path, theme, caption_pl, caption_en, symbolism_notes, ai_assisted, production_credits, status, reviewed_by, reviewed_at, created_by, created_at, updated_at, series_slug, series_order, is_planet, layer, pair_key, moral_quote_pl, moral_quote_en, alt_pl, alt_en, license, origin, width, height) VALUES (5, 'praca-organiczna-i-plodnosc-lemiesza-krok-1-realia', 'Praca Organiczna i Płodność Lemiesza (Krok 1: Realia)', 'Przymierze Lemiesza Studio', '/images/doktryna-jeza/hedgehog_realism_01.svg', 'agrarian_ethos', 'Polskie fabryki, rolnictwo i technologia: bogactwo rodzi się z suwerennej pracy, nie z długu zbrojeniowego.', 'Polish industry, agriculture, and innovation: wealth arises from sovereign labor, not debt-financed arms.', 'Realistyczne przełożenie: lemiesz i spichlerze tworzą realną potęgę cywilizacyjną.', 1, 'Przymierze Lemiesza Studio · SVG Design Canon 04', 'draft', NULL, NULL, 'seed:series-corpus', '2026-10-16 07:21:09', '2026-10-16 07:21:09', 'doktryna-jeza', 1, 0, 'realism', 'step_1_work', 'Płodny lemiesz tworzy bogactwo narodu; bezpłodny miecz trawi jego zasoby.', 'The fertile plowshare creates national wealth; the sterile sword consumes its resources.', NULL, NULL, NULL, 'static', NULL, NULL);
INSERT INTO campaign_posters (id, slug, title, artist_or_author, image_path, theme, caption_pl, caption_en, symbolism_notes, ai_assisted, production_credits, status, reviewed_by, reviewed_at, created_by, created_at, updated_at, series_slug, series_order, is_planet, layer, pair_key, moral_quote_pl, moral_quote_en, alt_pl, alt_en, license, origin, width, height) VALUES (6, 'pinceta-dwoch-drapieznikow-krok-2-alegoria', 'Pinceta Dwóch Drapieżników (Krok 2: Alegoria)', 'Przymierze Lemiesza Studio', '/images/doktryna-jeza/hedgehog_allegory_02.svg', 'sovereignty_peace', 'Jeż w puszczy między Niedźwiedziem ze Wschodu a Wilkiem w uprzęży z Zachodu.', 'The hedgehog in the forest between the Bear from the East and the harnessed Wolf from the West.', 'Zasada podwójnego dystansu: żaden drapieżnik nie jest obrońcą jeża.', 1, 'Przymierze Lemiesza Studio · SVG Design Canon 04', 'draft', NULL, NULL, 'seed:series-corpus', '2026-10-16 07:21:09', '2026-10-16 07:21:09', 'doktryna-jeza', 2, 0, 'allegory', 'step_2_pincers', 'Gdy dwa wilki dzielą las, naiwny jeż nie wstępuje do żadnej watahy, bo dla obu jest tylko mięsem.', 'When two predators divide the forest, the wise hedgehog joins neither pack, for to both he is only prey.', NULL, NULL, NULL, 'static', NULL, NULL);
INSERT INTO campaign_posters (id, slug, title, artist_or_author, image_path, theme, caption_pl, caption_en, symbolism_notes, ai_assisted, production_credits, status, reviewed_by, reviewed_at, created_by, created_at, updated_at, series_slug, series_order, is_planet, layer, pair_key, moral_quote_pl, moral_quote_en, alt_pl, alt_en, license, origin, width, height) VALUES (7, 'kleszcze-imperializmow-i-podwojny-dystans-krok-2-realia', 'Kleszcze Imperializmów i Podwójny Dystans (Krok 2: Realia)', 'Przymierze Lemiesza Studio', '/images/doktryna-jeza/hedgehog_realism_02.svg', 'sovereignty_peace', 'Geopolityczne kleszcze: odrzucenie roli frontowego zderzaka na rzecz suwerennego podwójnego dystansu.', 'Geopolitical pincers: refusing the role of a forward buffer in favor of sovereign double distance.', 'Realia geopolityki: unikanie porozumień ponad naszymi głowami poprzez status neutralnego pomostu.', 1, 'Przymierze Lemiesza Studio · SVG Design Canon 04', 'draft', NULL, NULL, 'seed:series-corpus', '2026-10-16 07:21:09', '2026-10-16 07:21:09', 'doktryna-jeza', 2, 0, 'realism', 'step_2_pincers', 'Równy dystans strategiczny zapobiega nowym rozbiorom i cudzym dyktatom.', 'Equal strategic distance prevents partition and foreign subjugation.', NULL, NULL, NULL, 'static', NULL, NULL);
INSERT INTO campaign_posters (id, slug, title, artist_or_author, image_path, theme, caption_pl, caption_en, symbolism_notes, ai_assisted, production_credits, status, reviewed_by, reviewed_at, created_by, created_at, updated_at, series_slug, series_order, is_planet, layer, pair_key, moral_quote_pl, moral_quote_en, alt_pl, alt_en, license, origin, width, height) VALUES (8, 'bariera-bolu-i-niestrawnosc-kolcow-krok-3-alegoria', 'Bariera Bólu i Niestrawność Kolców (Krok 3: Alegoria)', 'Przymierze Lemiesza Studio', '/images/doktryna-jeza/hedgehog_allegory_03.svg', 'history_warning', 'Zwinięcie w kulę: stalowe kolce ranią łapy drapieżnika. Koszt ataku przekracza zysk.', 'Coiling into a ball: steel spines injure the predator’s paws. The cost of attack exceeds the gain.', 'Niestrawność: drapieżnik odskakuje w bólu, wiedząc że zjedzenie jeża to pewna śmierć.', 1, 'Przymierze Lemiesza Studio · SVG Design Canon 04', 'draft', NULL, NULL, 'seed:series-corpus', '2026-10-16 07:21:09', '2026-10-16 07:21:09', 'doktryna-jeza', 3, 0, 'allegory', 'step_3_defense', 'Nie musisz pokonać imperium w polu – musisz sprawić, by dotknięcie twojej ziemi bolało je bardziej niż zysk.', 'You do not need to defeat an empire in open field; you only must ensure touching your soil inflicts unbearable pain.', NULL, NULL, NULL, 'static', NULL, NULL);
INSERT INTO campaign_posters (id, slug, title, artist_or_author, image_path, theme, caption_pl, caption_en, symbolism_notes, ai_assisted, production_credits, status, reviewed_by, reviewed_at, created_by, created_at, updated_at, series_slug, series_order, is_planet, layer, pair_key, moral_quote_pl, moral_quote_en, alt_pl, alt_en, license, origin, width, height) VALUES (9, 'asymetryczne-nasycenie-terenu-i-obrona-cywilna-krok-3-realia', 'Asymetryczne Nasycenie Terenu i Obrona Cywilna (Krok 3: Realia)', 'Przymierze Lemiesza Studio', '/images/doktryna-jeza/hedgehog_realism_03.svg', 'history_warning', 'Tanie drony rozpoznawczo-uderzeniowe, miny inżynieryjne i schrony dla 100% ludności cywilnej.', 'Low-cost reconnaissance and strike drones, defensive saturation, and shelters for 100% of the civilian population.', 'Asymetria kosztów: nowoczesna obrona terytorialna uniemożliwia okupację.', 1, 'Przymierze Lemiesza Studio · SVG Design Canon 04', 'draft', NULL, NULL, 'seed:series-corpus', '2026-10-16 07:21:09', '2026-10-16 07:21:09', 'doktryna-jeza', 3, 0, 'realism', 'step_3_defense', 'Nie potrzebujemy Sparty – koszt agresji na Polskę musi być dla każdego militarnym samobójstwem.', 'We do not need Sparta; the cost of attacking Poland must be military suicide for any aggressor.', NULL, NULL, NULL, 'static', NULL, NULL);
INSERT INTO campaign_posters (id, slug, title, artist_or_author, image_path, theme, caption_pl, caption_en, symbolism_notes, ai_assisted, production_credits, status, reviewed_by, reviewed_at, created_by, created_at, updated_at, series_slug, series_order, is_planet, layer, pair_key, moral_quote_pl, moral_quote_en, alt_pl, alt_en, license, origin, width, height) VALUES (10, 'spokojny-dukt-i-oaza-pokoju-krok-4-alegoria', 'Spokojny Dukt i Oaza Pokoju (Krok 4: Alegoria)', 'Przymierze Lemiesza Studio', '/images/doktryna-jeza/hedgehog_allegory_04.svg', 'sovereignty_peace', 'Drapieżniki omijają polanę jeża szerokim łukiem; jeż bezpiecznie wyprowadza młode.', 'Predators bypass the hedgehog glade at a wide distance; the hedgehog safely leads its young.', 'Triumf mądrości natury: zachowanie życia i przyszłości kolejnych pokoleń.', 1, 'Przymierze Lemiesza Studio · SVG Design Canon 04', 'draft', NULL, NULL, 'seed:series-corpus', '2026-10-16 07:21:09', '2026-10-16 07:21:09', 'doktryna-jeza', 4, 0, 'allegory', 'step_4_peace', 'Najwyższą sztuką wojny jest zachowanie pokoju dzięki sile własnych kolców i mądrości rozumu.', 'The supreme art of war is preserving peace through the strength of your own quills and wisdom.', NULL, NULL, NULL, 'static', NULL, NULL);
INSERT INTO campaign_posters (id, slug, title, artist_or_author, image_path, theme, caption_pl, caption_en, symbolism_notes, ai_assisted, production_credits, status, reviewed_by, reviewed_at, created_by, created_at, updated_at, series_slug, series_order, is_planet, layer, pair_key, moral_quote_pl, moral_quote_en, alt_pl, alt_en, license, origin, width, height) VALUES (11, 'zbrojna-neutralnosc-i-most-tranzytowy-krok-4-realia', 'Zbrojna Neutralność i Most Tranzytowy (Krok 4: Realia)', 'Przymierze Lemiesza Studio', '/images/doktryna-jeza/hedgehog_realism_04.svg', 'sovereignty_peace', 'Polska jako nietykalna Oaza Pokoju na wzór Austrii 1955 i Szwajcarii, most handlowy Wschód-Zachód.', 'Poland as an inviolable Oasis of Peace modelled after Austria 1955 and Switzerland, a thriving trade bridge.', 'Geopolityczny zysk: suwerenny hub handlowy w sercu Europy.', 1, 'Przymierze Lemiesza Studio · SVG Design Canon 04', 'draft', NULL, NULL, 'seed:series-corpus', '2026-10-16 07:21:09', '2026-10-16 07:21:09', 'doktryna-jeza', 4, 0, 'realism', 'step_4_peace', 'Neutralność przekształca geopolityczne kleszcze w niezbędny dla świata pomost.', 'Armed neutrality turns geopolitical pincers into an indispensable continental bridge.', NULL, NULL, NULL, 'static', NULL, NULL);
INSERT INTO campaign_posters (id, slug, title, artist_or_author, image_path, theme, caption_pl, caption_en, symbolism_notes, ai_assisted, production_credits, status, reviewed_by, reviewed_at, created_by, created_at, updated_at, series_slug, series_order, is_planet, layer, pair_key, moral_quote_pl, moral_quote_en, alt_pl, alt_en, license, origin, width, height) VALUES (12, 'geopolityczne-imadlo', 'Geopolityczne Imadło — Z Kleszczy Imperializmów w Suwerenny Pomost', 'Przymierze Lemiesza Studio (malarstwo olejne, styl Józefa Chełmońskiego & Jacka Malczewskiego)', '/images/imadlo_geopolityczne_hero.jpg', 'history_warning', 'Polska w geopolitycznym imadle: dwie imperialne szczęki zaciskające się ze Wschodu i Zachodu nie zdołają zmiażdżyć hartowanego lemiesza suwerennej pracy narodowej.', 'Poland in the geopolitical vice: two imperial jaws tightening from East and West cannot crush the tempered plowshare of sovereign national labor.', 'Metafora Imadła i Kleszczy (Canon 01 §2 Filar IV; Canon 04): Odrzucenie Rapallo i wojny zastępczej poprzez Podwójny Dystans i niezłomny opór lemiesza.', 1, 'Koncept: Bogdan Zięba (Przymierze Lemiesza); obraz olejny w stylu polskiego realizmu XIX w. (Józef Chełmoński) wspomagany AI (static/images/imadlo_geopolityczne_hero.jpg).', 'draft', NULL, NULL, 'seed:series-corpus', '2026-10-16 10:29:22', '2026-10-16 10:29:22', 'doktryna-jeza', 0, 1, 'standalone', NULL, 'Równy dystans strategiczny zapobiega zmiażdżeniu w obcym imadle i przekształca kleszcze w niezbędny dla świata pomost.', 'Equal strategic distance prevents being crushed in a foreign vice and turns geopolitical pincers into an indispensable bridge.', NULL, NULL, NULL, 'static', NULL, NULL);
INSERT INTO campaign_posters (id, slug, title, artist_or_author, image_path, theme, caption_pl, caption_en, symbolism_notes, ai_assisted, production_credits, status, reviewed_by, reviewed_at, created_by, created_at, updated_at, series_slug, series_order, is_planet, layer, pair_key, moral_quote_pl, moral_quote_en, alt_pl, alt_en, license, origin, width, height) VALUES (13, 'kto-pierwszy-byl-fakirem-delikatna-rownowaga-wladzy', 'Kto pierwszy był fakirem? — Delikatna Równowaga Władzy', 'Przymierze Lemiesza (Satyra)', '/images/cartoons/korowod_01_fakir.jpg', 'sovereignty_peace', 'Polityk jako Fakir: ekwilibrystyka na ostrych nastrojach społecznych, udawanie odporności na ból przed kamerami i zaklinanie fujarką PR-u syczącej kobry długu i kryzysu.', 'The Politician as Fakir: balancing on the sharp nails of public discontent while desperately playing the PR flute to charm the cobra of debt and crisis.', 'Odcinek 1 serii satyrycznej «Korowód Władzy» opartej o wersy Leszka Aleksandra Moczulskiego i Marka Grechuty (1971).', 1, 'Koncepcja i scenariusz: Zespół Lemiesza. Generacja wizualna: AI (styl karykatury redakcyjnej).', 'human_approved', NULL, NULL, 'admin', '2026-11-01 05:51:45', '2026-11-01 05:51:45', 'korowod-wladzy', 1, 1, 'standalone', NULL, 'Kto pierwszy był fakirem? Kto pierwszy astrologiem? Kto pierwszy został królem? A kto chciał zostać bogiem?', 'Who was the first to be a fakir? Who was the first astrologer?', NULL, NULL, NULL, 'static', NULL, NULL);
INSERT INTO campaign_posters (id, slug, title, artist_or_author, image_path, theme, caption_pl, caption_en, symbolism_notes, ai_assisted, production_credits, status, reviewed_by, reviewed_at, created_by, created_at, updated_at, series_slug, series_order, is_planet, layer, pair_key, moral_quote_pl, moral_quote_en, alt_pl, alt_en, license, origin, width, height) VALUES (14, 'kto-pierwszy-byl-astrologiem-horoskop-sondazowy', 'Kto pierwszy był astrologiem? — Horoskop Sondażowy', 'Przymierze Lemiesza (Satyra)', '/images/cartoons/korowod_02_astrolog.jpg', 'sovereignty_peace', 'Polityk jako Astrolog: ucieczka w sondażowe konstelacje, czytanie z wykresów słupkowych i horoskopów medialnych, podczas gdy pod nogami toną realia gospodarcze i codzienny byt Polaków.', 'The Politician as Astrologer: gazing into the constellations of polls and media predictions while sinking into the mud of economic reality.', 'Odcinek 2 serii satyrycznej «Korowód Władzy» opartej o utwór Grechuty i Moczulskiego. Przejście od iluzji (Fakir) do urojonego panowania nad losem (Astrolog).', 1, 'Koncepcja i scenariusz: Zespół Lemiesza. Generacja wizualna: AI (styl karykatury redakcyjnej).', 'human_approved', NULL, NULL, 'admin', '2026-11-01 12:06:14', '2026-11-01 12:06:14', 'korowod-wladzy', 2, 0, 'standalone', NULL, 'Kto pierwszy był astrologiem? Kto pierwszy został królem? A kto chciał zostać bogiem?', 'Who was the first astrologer? Who was the first to become king?', NULL, NULL, NULL, 'static', NULL, NULL);
INSERT INTO campaign_posters (id, slug, title, artist_or_author, image_path, theme, caption_pl, caption_en, symbolism_notes, ai_assisted, production_credits, status, reviewed_by, reviewed_at, created_by, created_at, updated_at, series_slug, series_order, is_planet, layer, pair_key, moral_quote_pl, moral_quote_en, alt_pl, alt_en, license, origin, width, height) VALUES (15, 'austria-zamek-w-parlamencie', 'Kto decyduje o wysłaniu żołnierza? Austria i sojusz z artykułem 5', 'Przymierze Lemiesza (schemat)', '/images/journal/austria-zamek-w-parlamencie.svg', 'sovereignty_peace', 'Austria decyduje za każdym razem osobno, w sojuszu z artykułem 5 decyzja zapada wcześniej w umowie.', NULL, NULL, 1, 'Schemat SVG przygotowany z pomocą AI na podstawie tekstu artykułu; wymaga przeglądu człowieka.', 'human_approved', 'dev', '2026-11-07 13:28:54', 'dev', '2026-11-07 13:28:54', '2026-11-07 13:28:54', NULL, 0, 0, 'standalone', NULL, NULL, NULL, 'Schemat w dwóch kolumnach. Po lewej Austria: prośba o udział w misji, zgoda rządu, zgoda parlamentu, potem decyzja tak albo nie, a klucz leży w Wiedniu. Po prawej sojusz z artykułem 5: atak na jednego członka jest uznany za atak na wszystkich, a zobowiązanie do pomocy wynika z umowy.', NULL, 'CC0 (własny schemat redakcji)', 'static', 900, 520);
INSERT INTO campaign_posters (id, slug, title, artist_or_author, image_path, theme, caption_pl, caption_en, symbolism_notes, ai_assisted, production_credits, status, reviewed_by, reviewed_at, created_by, created_at, updated_at, series_slug, series_order, is_planet, layer, pair_key, moral_quote_pl, moral_quote_en, alt_pl, alt_en, license, origin, width, height) VALUES (16, 'austria-male-kroki', 'Schodki małych kroków: od neutralności do współpracy z NATO', 'Przymierze Lemiesza (schemat)', '/images/journal/austria-male-kroki.svg', 'sovereignty_peace', 'Każdy mały krok to więcej współpracy. Bezpiecznikiem jest zgoda parlamentu.', NULL, NULL, 1, 'Schemat SVG przygotowany z pomocą AI na podstawie tekstu artykułu; wymaga przeglądu człowieka.', 'human_approved', 'dev', '2026-11-07 13:28:54', 'dev', '2026-11-07 13:28:54', '2026-11-07 13:28:54', NULL, 0, 0, 'standalone', NULL, NULL, NULL, 'Rysunek czterech schodków rosnących w górę: 1955 neutralność zapisana w prawie, 1995 Partnerstwo dla Pokoju, PARP czyli wspólne planowanie i ocena wojska, ITPP czyli program wspólnych celów z NATO. Nad schodkami dwie ramki: bezpiecznik, czyli zamek parlamentu, oraz ostrzeżenie, że rośnie pokusa szykowania wojska do misji za granicą.', NULL, 'CC0 (własny schemat redakcji)', 'static', 900, 520);

