-- journal_article_texts: 9 row(s)
INSERT INTO journal_article_texts (id, article_id, locale, title, lead, body, revision, status, ai_assisted, published_title, published_lead, published_body, published_revision, published_at, published_by, created_at, updated_at, blocks_json, published_blocks_json, layout_columns, published_layout_columns) VALUES (1, 1, 'pl', 'Geometria posłuszeństwa. O rzędach, rządach, Kartezjuszu i nieszczęsnym losie polnego chwastu', 'Abstrakt  Współczesna filozofia państwowa stawia znak równości pomiędzy „człowiekiem porządnym” a „obywatelem praworządnym”. Niniejszy szkic dokonuje bezlitosnej dekonstrukcji tego utożsamienia. Sięgając do słowiańskiego rdzenia słów „rząd”, „rządzić” i „urządzać”, a także do Kartezjańskiego przewrotu geometrycznego, obnażamy istotę nowożytnego państwa jako gigantycznej plantacji. Urzędnik to ten, który urządza rzędy; praworządność to dyscyplina trzymania się osi współrzędnych; a sam rząd to mechanizm opielacza wycinającego wszelkie „chwasty nonkonformistyczne”. Przeciwstawiamy kartezjańskiej monokulturze koszar żywą mądrość Lemiesza i naturalny ekosystem wolnego człowieka.', 'I. Filologia tresury: Kto stoi po-rządku?

Kiedy życzliwy legalista prawi nam morały o konieczności bycia „człowiekiem porządnym”, warto na chwilę zatrzymać potok jego komunałów i zapytać o elementarną gramatykę pojęć. Skąd wziął się ów mityczny „porządek”?

Słownik języka polskiego nie pozostawia złudzeń. Porządny to ten, który postępuje po-rządku — dokładnie tak, jak wyznacza kolejka, linia, redlina lub szyk bojowy. Porządny człowiek to w istocie nic innego jak ludź karnie stojący w rzędzie.

Nie ma w tym pojęciu pierwotnie ani cnoty sprawiedliwości (iustitia), ani miłosierdzia, ani metafizycznej prawości. Jest wyłącznie przestrzenna dyscyplina:

Jeśli stoisz w szeregu i nie wystajesz — jesteś porządny.
Jeśli opuścisz wyznaczone ci pole w tabeli — stajesz się nie-rządnikiem, elementem wywrotowym, nieporządnym.

Zadaniem każdego urzędnika jest bowiem — jak sama nazwa wskazuje — urządzanie rzędów. Urzędnik nie tworzy bytu; on go formatuje. Wciska żywego, wielowymiarowego człowieka w rubrykę, nadaje mu numer ewidencyjny, wyznacza odstęp od poprzednika i następcy. Z kolei rządzenie to technologia zarządzania tą geometryczną procesją.

Pojawia się tu jednak fundamentalne pęknięcie w gmachu państwowej propagandy: porządek może być przecież praworządny albo leworządny. Wystarczy zmienić orientację wektora. Gdy władzę obejmuje lewica, nakazuje maszerować wedle dogmatów postępu społecznego; gdy prawica — wedle imperialnego zaciągu i narodowego obowiązku. W obu wypadkach jednostka pozostaje zredukowana do funkcji szeregowca. Kto decyduje o tym, która strona jest „praworządna”? Zawsze ten, kto aktualnie trzyma w dłoni sznurek mierniczy i bat. Prawo staje się po prostu technicznym regulaminem marszu.

II. Układ Kartezjański: Jak matematyka zabiła duszę i stworzyła Lewiatana

Nie sposób pojąć nowoczesnego rządu bez zrozumienia przewrotu, jakiego w XVII wieku dokonał René Descartes. Kartezjusz, ogłaszając świat materialny (res extensa) bezduszną maszyną podległą czystej geometrii, podarował władcom narzędzie ostateczne: dwuwymiarowy układ współrzędnych.

Spójrzmy na terminologię matematyczną, która w języku polskim zdradza swój opresyjny rodowód:

Mamy oś poziomą — oś odciętych (abscysa). Jej zadaniem jest odcięcie tego, co jednostkowe i niepowtarzalne.
Mamy oś pionową — oś rzędnych (ordynata, od łacińskiego ordo — rząd, ład, klasa).

Przecięcie tych dwóch osi pod kątem prostym tworzy siatkę, w którą Lewiatan może schwytać całe społeczeństwo. W układzie kartezjańskim nie ma miejsca na tajemnicę sumienia, na osobistą relację z Bogiem, na swojski obyczaj ani na wolną wolę. Wszystko staje się punktem 
(
𝑋
,
𝑌
)
(X,Y):

Obywatel to punkt o współrzędnych 
(
𝑃
𝐸
𝑆
𝐸
𝐿
,
𝑁
𝐼
𝑃
)
(PESEL,NIP).
Dochód to wektor ściągany podatkiem w dół.
Młody mężczyzna to punkt mobilizacyjny, który w razie potrzeby przesuwa się po osi rzędnych wprost w błoto okopu.

Układy „rządowe” — te koalicyjne targi, podziały ministerstw, synekury w spółkach skarbu państwa — to nic innego jak geometryczna parcelacja tej samej kartezjańskiej siatki. Partie polityczne (od łacińskiego pars — część) dzielą społeczeństwo na równe ćwiartki wykresu. Jedna partia zarządza rzędami od 1 do 100, druga od 101 do 200. Kłócą się zażarcie o to, kto ma trzymać kredę przy tablicy, ale obie panicznie boją się sytuacji, w której ktoś zmaże samą siatkę.

III. Monokultura ziemniaczana: Dlaczego rolnik sadzi w rzędach?

Aby pojąć naturę rządu, trzeba jednak porzucić kawiarnie filozofów i wyjść na pole — tam, gdzie ziemię pruje lemiesz. Rolnik wie o rządzeniu więcej niż profesor politologii, bo rolnik od stuleci sadzi ziemniaki w rzędach na grządkach.

Zadajmy sobie pytanie z pozoru naiwne: dlaczego ziemniaki sadzi się w rzędach?

Czy ziemniak jako roślina pragnie rosnąć w rzędzie? Skądże znowu! Ziemniak w stanie dzikim, w andyjskiej dolinie, rośnie swobodnie w wielogatunkowej symbiozie. Rząd nie jest potrzebny ziemniakowi. Rząd jest potrzebny maszynie.

Ziemniaki sadzi się w równych redlinach z dwóch pragmatycznych powodów:

Dla wygody kontroli i eksploatacji: Rząd pozwala rolnikowi szybko oszacować plon, policzyć bulwy i zaplanować zbiór.
Aby wjechać z mechanicznym opielaczem.

Gdy ziemniaki stoją w karnym rzędzie, między rzędy wjeżdża żelazny kultywator, brona lub ciągnik z opryskiwaczem. Co jest celem tej maszyny? Likwidacja chwastów nonkonformistycznych.

Polny mak, chaber bławatek, rumianek, oset czy mniszek lekarski — to rośliny wolne. Miały czelność wykiełkować tam, gdzie powiał wiatr, a nie tam, gdzie wyznaczył kartezjański sznurek gospodarza. Nie pasują do monokultury. Z punktu widzenia urzędnika polowego są sabotażystami: zabierają wilgoć, rzucają cień na bulwę państwową, psują estetykę plantacji. Zostają więc ścięte motyką, podcięte nożem pielnika lub zatrute glifosatem.

Nowożytne państwo partyjne traktuje naród dokładnie jak pole ziemniaków:

Masz wschodzić w wyznaczonym terminie (szkoła powszechna).
Masz rosnąć w równej redlinie (system kredytowo-podatkowy).
Masz dać się obsypać ziemią, byś nie widział horyzontu (państwowa propaganda i telewizja).
A jeśli wyrośniesz poza rzędem — jeśli odważysz się głosić neutralność, pacyfizm, obronę własności czy wolność od przymusowych danin — natychmiast uznaje się cię za „chwast obcej narracji” i wysyła sejmowy opielacz w postaci ustawy o wrogach ludu (druku 3003) z nożem konfiskaty i kajdan.
IV. Bunt chabrów: Przymierze Lemiesza przeciwko machinie kartezjańskiej

Kiedy więc nasz poczciwy kolega powiada z nabożeństwem: „Porządny to praworządny... w tym porządku co przyjęto w Polsce Prezydent ma rolę reprezentacyjną, a rządu i sądów trzeba słuchać” — odpowiadamy mu:

Mylisz, przyjacielu, Boży ład stworzenia z geometrią obozowego placu apelowego.

Prawdziwy ład nie rodzi się z ustawiania ludzi w rzędy pod kartezjańską linijkę.

Prawdziwy ład rodzi się w rodzinie, w lokalnej wspólnocie, na własnym zagonie, w rzemiośle i w suwerennym sumieniu.
Naturalny las nie zna rzędów — a przecież trwa przez tysiąclecia, odporny na burze i szkodniki. To plantacja sosnowa, posadzona pod linijkę przez leśnika, pali się od jednej iskry i pada łupem pierwszego lepszego kornika.

Wizja państwa jako kartezjańskiego kombinatu to domena Drogi Miecza. To tam król z 1 Księgi Samuela potrzebuje idealnych szeregów, by móc łatwo przeliczyć baganety, pobrać dziesięcinę i posłać rzędy młodzieńców na rzeź w imię cudzych interesów.

Droga Lemiesza to powrót do organicznej prawdy o człowieku:

Człowiek nie jest wektorem w tabeli Excela. Posiada godność nadaną przez Stwórcę, której żaden sejmowy geometra nie ma prawa mierzyć.
Wolność to prawo do wyjścia z rzędu — prawo do bycia „chwastem nonkonformistycznym”, który nie kłania się partyjnym sztandarom i nie daje się zaprząc w koalicyjne uprzęże.
Rząd, który zamiast służyć pokojowi i bezpieczeństwu granic zaczyna zajmować się „urządzaniem rzędów” i tępieniem wolności myśli, traci moralny mandat do żądania posłuszeństwa.

Nie bądźmy „ludźmi porządnymi” według definicji urzędników. Bądźmy ludźmi prawymi — takimi, którzy zamiast stać w potulnym rzędzie na rzeź, potrafią przekuć miecze na lemiesze, a na własnej ziemi stanąć jak najeżony, wolny i niemożliwy do sformatowania gospodarz.', 1, 'human_approved', 0, 'Geometria posłuszeństwa. O rzędach, rządach, Kartezjuszu i nieszczęsnym losie polnego chwastu', 'Abstrakt  Współczesna filozofia państwowa stawia znak równości pomiędzy „człowiekiem porządnym” a „obywatelem praworządnym”. Niniejszy szkic dokonuje bezlitosnej dekonstrukcji tego utożsamienia. Sięgając do słowiańskiego rdzenia słów „rząd”, „rządzić” i „urządzać”, a także do Kartezjańskiego przewrotu geometrycznego, obnażamy istotę nowożytnego państwa jako gigantycznej plantacji. Urzędnik to ten, który urządza rzędy; praworządność to dyscyplina trzymania się osi współrzędnych; a sam rząd to mechanizm opielacza wycinającego wszelkie „chwasty nonkonformistyczne”. Przeciwstawiamy kartezjańskiej monokulturze koszar żywą mądrość Lemiesza i naturalny ekosystem wolnego człowieka.', 'I. Filologia tresury: Kto stoi po-rządku?

Kiedy życzliwy legalista prawi nam morały o konieczności bycia „człowiekiem porządnym”, warto na chwilę zatrzymać potok jego komunałów i zapytać o elementarną gramatykę pojęć. Skąd wziął się ów mityczny „porządek”?

Słownik języka polskiego nie pozostawia złudzeń. Porządny to ten, który postępuje po-rządku — dokładnie tak, jak wyznacza kolejka, linia, redlina lub szyk bojowy. Porządny człowiek to w istocie nic innego jak ludź karnie stojący w rzędzie.

Nie ma w tym pojęciu pierwotnie ani cnoty sprawiedliwości (iustitia), ani miłosierdzia, ani metafizycznej prawości. Jest wyłącznie przestrzenna dyscyplina:

Jeśli stoisz w szeregu i nie wystajesz — jesteś porządny.
Jeśli opuścisz wyznaczone ci pole w tabeli — stajesz się nie-rządnikiem, elementem wywrotowym, nieporządnym.

Zadaniem każdego urzędnika jest bowiem — jak sama nazwa wskazuje — urządzanie rzędów. Urzędnik nie tworzy bytu; on go formatuje. Wciska żywego, wielowymiarowego człowieka w rubrykę, nadaje mu numer ewidencyjny, wyznacza odstęp od poprzednika i następcy. Z kolei rządzenie to technologia zarządzania tą geometryczną procesją.

Pojawia się tu jednak fundamentalne pęknięcie w gmachu państwowej propagandy: porządek może być przecież praworządny albo leworządny. Wystarczy zmienić orientację wektora. Gdy władzę obejmuje lewica, nakazuje maszerować wedle dogmatów postępu społecznego; gdy prawica — wedle imperialnego zaciągu i narodowego obowiązku. W obu wypadkach jednostka pozostaje zredukowana do funkcji szeregowca. Kto decyduje o tym, która strona jest „praworządna”? Zawsze ten, kto aktualnie trzyma w dłoni sznurek mierniczy i bat. Prawo staje się po prostu technicznym regulaminem marszu.

II. Układ Kartezjański: Jak matematyka zabiła duszę i stworzyła Lewiatana

Nie sposób pojąć nowoczesnego rządu bez zrozumienia przewrotu, jakiego w XVII wieku dokonał René Descartes. Kartezjusz, ogłaszając świat materialny (res extensa) bezduszną maszyną podległą czystej geometrii, podarował władcom narzędzie ostateczne: dwuwymiarowy układ współrzędnych.

Spójrzmy na terminologię matematyczną, która w języku polskim zdradza swój opresyjny rodowód:

Mamy oś poziomą — oś odciętych (abscysa). Jej zadaniem jest odcięcie tego, co jednostkowe i niepowtarzalne.
Mamy oś pionową — oś rzędnych (ordynata, od łacińskiego ordo — rząd, ład, klasa).

Przecięcie tych dwóch osi pod kątem prostym tworzy siatkę, w którą Lewiatan może schwytać całe społeczeństwo. W układzie kartezjańskim nie ma miejsca na tajemnicę sumienia, na osobistą relację z Bogiem, na swojski obyczaj ani na wolną wolę. Wszystko staje się punktem 
